# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PHYSICAL APPEARANCE vs. PERSONALITY TRAITS (THEME 3)</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">WHAT DOES HE/SHE LOOK LIKE? (APPEARANCE)</text>\n  <text x="42" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">• Height &amp; Build (Boy ve Yapı): verb "to be"</text>\n  <text x="50" y="110" font-size="10.5" fill="#1e40af">tall, of medium height, short / slim, well-built, plump</text>\n  <text x="42" y="134" font-size="11" font-weight="bold" fill="#1e3a8a">• Hair &amp; Eyes (Saç ve Göz): "have got / has got"</text>\n  <text x="50" y="150" font-size="10.5" fill="#1e40af">straight, wavy, curly, spiky, fair/blonde, dark hair</text>\n  <text x="50" y="166" font-size="10.5" fill="#1e40af">hazel, green, brown, blue, almond-shaped eyes</text>\n  <text x="42" y="190" font-size="11" font-weight="bold" fill="#1e3a8a">• Age &amp; Features: middle-aged, teen, freckles, beard</text>\n  <text x="182" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">She is tall and slim. She has got long wavy hair.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fdf2f8" stroke="#db2777" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9d174d">WHAT IS HE/SHE LIKE? (PERSONALITY)</text>\n  <text x="377" y="94" font-size="11" font-weight="bold" fill="#831843">• Positive Traits (Olumlu Karakter Sıfatları):</text>\n  <text x="385" y="110" font-size="10.5" fill="#9d174d">generous (cömert), reliable/trustworthy (güvenilir),</text>\n  <text x="385" y="126" font-size="10.5" fill="#9d174d">outgoing (dışa dönük), honest (dürüst), punctual (dakik)</text>\n  <text x="385" y="142" font-size="10.5" fill="#9d174d">easy-going (uyumlu), patient (sabırlı), modest (mütevazı)</text>\n  <text x="377" y="168" font-size="11" font-weight="bold" fill="#831843">• Negative Traits (Olumsuz Karakter Sıfatları):</text>\n  <text x="385" y="184" font-size="10.5" fill="#9d174d">stubborn (inatçı), stingy/mean (cimri), selfish (bencil),</text>\n  <text x="385" y="200" font-size="10.5" fill="#9d174d">jealous (kıskanç), Moody (değişken ruhlu), arrogant</text>\n  <text x="517" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#be185d">He is reliable and generous, never selfish.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">COMPARATIVE &amp; SUPERLATIVE ADJECTIVES (KARŞILAŞTIRMA VE ÜSTÜNLÜK)</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">COMPARATIVE (İKİ KİŞİ/NESNE: DAHA ...)</text>\n  <text x="42" y="94" font-size="11" font-weight="bold" fill="#14532d">• Short Adjectives (1 hece): adj + -er + than</text>\n  <text x="50" y="110" font-size="10.5" fill="#166534">tall → taller than | slim → slimmer than | shy → shyer</text>\n  <text x="50" y="126" font-size="10.5" fill="#166534">happy → happier than (-y düşer, -ier gelir)</text>\n  <text x="42" y="150" font-size="11" font-weight="bold" fill="#14532d">• Long Adjectives (2+ hece): more + adj + than</text>\n  <text x="50" y="166" font-size="10.5" fill="#166534">generous → more generous than</text>\n  <text x="50" y="182" font-size="10.5" fill="#166534">hardworking → more hardworking than</text>\n  <text x="42" y="206" font-size="11" font-weight="bold" fill="#14532d">• Equality: as + adj + as (Ece is as tall as Mert)</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">SUPERLATIVE (GRUP İÇİNDE: EN ...) &amp; IRREGULARS</text>\n  <text x="377" y="94" font-size="11" font-weight="bold" fill="#713f12">• Short Adjectives: the + adj + -est (in / of)</text>\n  <text x="385" y="110" font-size="10.5" fill="#854d0e">tall → the tallest | funny → the funniest in the class</text>\n  <text x="377" y="134" font-size="11" font-weight="bold" fill="#713f12">• Long Adjectives: the most + adj (in / of)</text>\n  <text x="385" y="150" font-size="10.5" fill="#854d0e">reliable → the most reliable friend of all</text>\n  <text x="377" y="174" font-size="11" font-weight="bold" fill="#b91c1c">• Irregular Adjectives (Düzensiz Sıfatlar):</text>\n  <text x="385" y="190" font-size="10.5" font-weight="bold" fill="#7f1d1d">good → better than → the best</text>\n  <text x="385" y="206" font-size="10.5" font-weight="bold" fill="#7f1d1d">bad → worse than → the worst</text>\n  <text x="385" y="222" font-size="10.5" font-weight="bold" fill="#7f1d1d">far → farther/further than → the farthest/furthest</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HOBBIES, FREE TIME ACTIVITIES &amp; EXPRESSING PREFERENCES</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">VERB COLLOCATIONS: PLAY / GO / DO</text>\n  <text x="42" y="96" font-size="11" font-weight="bold" fill="#581c87">• PLAY (Top oyunları, takım sporları ve çalgılar):</text>\n  <text x="50" y="112" font-size="10.5" fill="#6b21a8">play basketball, volleyball, chess, board games, the guitar</text>\n  <text x="42" y="138" font-size="11" font-weight="bold" fill="#581c87">• GO (-ing ile biten açık alan/hareket etkinlikleri):</text>\n  <text x="50" y="154" font-size="10.5" fill="#6b21a8">go hiking, cycling, swimming, camping, ice-skating</text>\n  <text x="42" y="180" font-size="11" font-weight="bold" fill="#581c87">• DO (Bireysel sporlar, dövüş sanatları, egzersiz):</text>\n  <text x="50" y="196" font-size="10.5" fill="#6b21a8">do archery, yoga, karate, gymnastics, puzzles, origami</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">EXPRESSING LIKES, DISLIKES &amp; INTERESTS</text>\n  <text x="377" y="96" font-size="11" font-weight="bold" fill="#7c2d12">• Strong Interest (+ V-ing / Noun):</text>\n  <text x="385" y="112" font-size="10.5" fill="#9a3412">be keen on / be fond of / be interested in / be crazy about</text>\n  <text x="385" y="128" font-size="10.5" fill="#9a3412">enjoy / love / like + V-ing (I am keen on taking photos.)</text>\n  <text x="377" y="154" font-size="11" font-weight="bold" fill="#7c2d12">• Dislikes (+ V-ing / Noun):</text>\n  <text x="385" y="170" font-size="10.5" fill="#9a3412">can\'t stand / dislike / hate + V-ing (He can\'t stand waiting.)</text>\n  <text x="377" y="196" font-size="11" font-weight="bold" fill="#7c2d12">• Preferences (Tercihler):</text>\n  <text x="385" y="212" font-size="10.5" fill="#9a3412">prefer V-ing to V-ing (I prefer reading to watching TV.)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
